sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.timelineData = c.data.timelineData;

};

sp_widget.css:
.timeline-container{

    margin-top:20px;
    padding:25px;

    border-radius:24px;

    background:linear-gradient(
        -45deg,
        #1B5E20,
        #2E7D32,
        #43A047,
        #66BB6A
    );

    background-size:400% 400%;

    animation:gradientMove 12s ease infinite;

    box-shadow:0 15px 35px rgba(0,0,0,.15);

    position:relative;

    overflow:hidden;
}

/* ==========================================
   ANIMATED GRADIENT
========================================== */

@keyframes gradientMove{

    0%{
        background-position:0% 50%;
    }

    50%{
        background-position:100% 50%;
    }

    100%{
        background-position:0% 50%;
    }
}

/* ==========================================
   FLOATING BLOBS
========================================== */

.timeline-container::before{

    content:"";

    position:absolute;

    width:250px;
    height:250px;

    border-radius:50%;

    background:rgba(255,255,255,.08);

    top:-100px;
    right:-80px;

    animation:blobFloat1 8s ease-in-out infinite;
}

.timeline-container::after{

    content:"";

    position:absolute;

    width:180px;
    height:180px;

    border-radius:50%;

    background:rgba(255,255,255,.06);

    bottom:-60px;
    left:-60px;

    animation:blobFloat2 10s ease-in-out infinite;
}

@keyframes blobFloat1{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(-20px);
    }

    100%{
        transform:translateY(0);
    }
}

@keyframes blobFloat2{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(20px);
    }

    100%{
        transform:translateY(0);
    }
}

/* ==========================================
   GROUP
========================================== */

.timeline-group{
    margin-bottom:35px;
    position:relative;
    z-index:2;
}

/* ==========================================
   TIME
========================================== */

.timeline-time{

    font-size:20px;
    font-weight:700;

    color:#fff;

    margin-bottom:15px;
    padding-left:10px;
}

.timeline-time i{

    margin-right:8px;

    animation:clockRotate 4s linear infinite;
}

@keyframes clockRotate{

    from{
        transform:rotate(0deg);
    }

    to{
        transform:rotate(360deg);
    }
}

/* ==========================================
   CARD
========================================== */

.timeline-card{

    position:relative;

    overflow:hidden;

    background:rgba(255,255,255,.12);

    backdrop-filter:blur(12px);
    -webkit-backdrop-filter:blur(12px);

    border:1px solid rgba(255,255,255,.18);

    border-radius:18px;

    padding:18px;

    margin-bottom:12px;

    display:flex;

    justify-content:space-between;
    align-items:center;

    color:#fff;

    box-shadow:0 4px 15px rgba(0,0,0,.08);

    animation:
        slideUp .6s ease forwards,
        cardFloat 6s ease-in-out infinite;

    opacity:0;

    transition:.3s;
}

/* Entry Animation */

.timeline-card:nth-child(1){
    animation-delay:.1s;
}

.timeline-card:nth-child(2){
    animation-delay:.2s;
}

.timeline-card:nth-child(3){
    animation-delay:.3s;
}

.timeline-card:nth-child(4){
    animation-delay:.4s;
}

@keyframes slideUp{

    from{
        opacity:0;
        transform:translateY(30px);
    }

    to{
        opacity:1;
        transform:translateY(0);
    }
}

@keyframes cardFloat{

    0%{
        transform:translateY(0);
    }

    50%{
        transform:translateY(-3px);
    }

    100%{
        transform:translateY(0);
    }
}

/* Hover */

.timeline-card:hover{

    transform:translateY(-5px) scale(1.02);

    background:rgba(255,255,255,.18);

    box-shadow:
        0 12px 30px rgba(0,0,0,.15),
        0 0 20px rgba(255,255,255,.15);
}

/* ==========================================
   SHIMMER
========================================== */

.timeline-card::before{

    content:'';

    position:absolute;

    top:0;
    left:-100%;

    width:100%;
    height:100%;

    background:linear-gradient(
        90deg,
        transparent,
        rgba(255,255,255,.15),
        transparent
    );

    transition:.8s;
}

.timeline-card:hover::before{

    left:100%;
}

/* ==========================================
   TEXT
========================================== */

.patient-name{

    font-size:16px;
    font-weight:700;

    color:#fff;
}

.medication-name{

    margin-top:5px;

    color:rgba(255,255,255,.85);
}

.ward-info{

    font-weight:600;

    color:#fff;
}

/* ==========================================
   STATUS BADGES
========================================== */

.status-badge{

    padding:8px 14px;

    border-radius:30px;

    font-size:12px;
    font-weight:700;
}

.given{

    background:#E8F5E9;
    color:#2E7D32;
}

.due{

    background:#FFF3E0;
    color:#EF6C00;

    animation:pulseDue 2s infinite;
}

.missed{

    background:#FFEBEE;
    color:#C62828;
}

.upcoming{

    background:#E3F2FD;
    color:#1565C0;
}

@keyframes pulseDue{

    0%{
        box-shadow:0 0 0 0 rgba(239,108,0,.6);
    }

    70%{
        box-shadow:0 0 0 12px rgba(239,108,0,0);
    }

    100%{
        box-shadow:0 0 0 0 rgba(239,108,0,0);
    }
}

/* ==========================================
   MOBILE
========================================== */

@media(max-width:768px){

    .timeline-card{

        flex-direction:column;
        align-items:flex-start;

        gap:12px;
    }

    .timeline-time{

        font-size:18px;
    }
}

